import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver.isSealed()
 */
public class NamespaceResolver_isSealed_TriageGen1Test {



    @Test
    public void testIsSealed_AfterSeal_True() {
        // Testing the state after the seal() method is called
        NamespaceResolver resolver = new NamespaceResolver();
        assertFalse("Should be false before calling seal()", resolver.isSealed());

        resolver.seal();

        assertTrue("Should be true after calling seal()", resolver.isSealed());
    }




}

