package org.apache.commons.jxpath.ri;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NamespaceResolver.isSealed()
 */
public class NamespaceResolver_isSealed_TriageGen1Test {







    @Test
    public void testIsSealed_AfterSeal_MultipleTimes() {
        // Testing idempotency of seal() and isSealed()
        NamespaceResolver resolver = new NamespaceResolver();

        resolver.seal();
        assertTrue(resolver.isSealed());

        resolver.seal(); // Calling seal again
        assertTrue("isSealed should remain true after multiple seal() calls", resolver.isSealed());
    }
}
